      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 8/3~14) 고등학교 1학년) 청소년의 온라인 문화와 SNS·밈 활용 경험에 관한 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.07.30. 11:18\n조회 13\n구독\n고유링크) 8/3~14) 중학교1학년~고등학교 1학년) 청소년의 온라인 문화와 SNS·밈 활용 경험에 관한 인터뷰\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n청소년의 SNS 활용 및 밈 사용 경험, 전반적인 온라인 문화에 대해 얘기를 나누는 자리입니다.\n▶조사 대상 :?(중학생, 고1)\n?- 현재 중학교 1학년~고등학교 1학년에 재학 중인 수도권 거주 남녀(고2, 고3 제외)\n▶진행 방식 : 한국리서치에서 진행되는 좌담회&인터뷰(조건에 따라 상이)\n▶일정: 8월 3일(월)~8월 14일(금) 중 조정 가능/ 시간은 추후 안내드립니다\n▶소요시간: 2시간 / 사례비: 10만원\n▶조사 장소 : 한국리서치 본사(9호선 언주역 인근)\n★신청해 주신 내용을 토대로 순차적으로 전화 드릴 예정입니다. 저희 직원과 통화 후 참여자 명단에 등록이 되셔야 참여 가능합니다.\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n조사기간 2026-08-03 ~ 2026-08-14일 중 하루\n소요시간 2시간\n사례비 100,000\n조사방법 2시간 1:1 인터뷰, 2시간 좌담회(조건에 따라 상이)\n안내사항 청소년 온라인 문화나 SNS 및 온라인 커뮤니티 등 다양한 온라인 문화를 잘 알고 있는 분을 찾습니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/756?refuser=23341&intro=2\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.07.30. 14:49 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n8/14) 보호자&여아 36개월 이상~10세( 초등학교 3학년) 자녀 - 신제품 맛 테스트\n좌담회알바좌담회카페\n26.07.30.\n댓글\n1\n고유링크) 8/3~14) 고등학교 1학년) 청소년의 온라인 문화와 SNS·밈 활용 경험에 관한 인터뷰\n좌담회알바좌담회카페\n26.07.30.\n댓글\n1\n고유링크) 8/3~14) 중학교3학년) 청소년의 온라인 문화와 SNS·밈 활용 경험에 관한 인터뷰\n좌담회알바좌담회카페\n26.07.30.\n댓글\n1\n고유링크) 8/3~14) 중학교2학년) 청소년의 온라인 문화와 SNS·밈 활용 경험에 관한 인터뷰\n좌담회알바좌담회카페\n26.07.30.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
