      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n8/11) 브랜드 아파트 자2 거주 중인 50대 남녀 ) 아파트 브랜드 인식 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.07.30. 19:07\n조회 21\n구독\n8/11) 브랜드 아파트 자2 거주 중인 50대 남녀 ) 아파트 브랜드 인식 좌담회\n신청하신분은 재신청 안하셔도 됩니다\n1.대상자\n브랜드 아파트(자2) 거주 중인 50대 남녀\n<진행 및 일정>\n8월 11일(화) 오후 4시, 저녁 7시\n<사례비>\n사례비: 5만원\n장소 : 경복궁역 인근\n<신청방법>\n1. 이름/생년월일/성별/기미혼여부/ 거주구 동/직업/연락처\n2. 현재 거주중인 아파트명 (예: 힐스테이트일산)\n3. 청약 통장 가입 여부 및 가입한 경우, 가입기간 및 납입 횟수\n4. 최근 1년 내 관심있게 봤던 청약 공고 아파트명 모두 기재\n5. 선호 아파트 브랜드명/ 비선호 아파트 브랜드명\n6. 조사 가능한 날짜 및 시간대\nhttps://forms.gle/ZByMyRhFGH7AgAgS9\n좋아요\n0\n'좋아요'로 마음을 나누세요!\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n8/10~18) 20-49세 남자) 흡연자 대상 오프라인 8월1,2차 설문조사 참여자 모집_신규 조사\n좌담회알바좌담회카페\n26.07.30.\n댓글\n0\n8/20~25) 28~49세 남성/ 28~39세 여성 ) 음료 좌담회(사전과제有)\n좌담회알바좌담회카페\n26.07.30.\n댓글\n0\n8/11) 브랜드 아파트 자2 거주 중인 50대 남녀 ) 아파트 브랜드 인식 좌담회\n좌담회알바좌담회카페\n26.07.30.\n댓글\n0\n8/10~19) 수도권 만23~59세 여성 ) 홈 케어 기기 유치조사\n좌담회알바좌담회카페\n26.07.30.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
